# region: shape
def shape(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: fold
def fold(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: render
def render(xs, offset=4):
    return [v + offset for v in xs]

# region: digest
def digest(xs, offset=4):
    return [v + offset for v in xs]

# region: intake
def intake(xs):
    return {'n': len(xs), 'total': max(xs)}

# region: gather
def gather(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return gather(intake(digest(render(fold(shape(raw))))))

