        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 4, 'total': 46, 'flags': ['n', 'total']})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 3, 'total': 32, 'flags': ['n', 'total']})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 3, 'total': 42, 'flags': ['n', 'total']})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'total': 35, 'flags': ['n', 'total']})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'total': 9, 'flags': ['n', 'total']})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'total': 42, 'flags': ['n', 'total']})
